script:
frappe.ready(() => {

    const applyRedBorder = () => {
        const widgets = document.querySelectorAll('.widget, .widget-number, .stat-card');

        widgets.forEach(widget => {
            const text = widget.innerText.toLowerCase();

            if (text.includes("outgoing")) {
                widget.classList.add("red-border");
            }
        });
    };

    // Retry because ERPNext loads dynamically
    let count = 0;
    const interval = setInterval(() => {
        applyRedBorder();
        count++;
        if (count > 10) clearInterval(interval);
    }, 500);

});

frappe.ui.form.on('Employee', {
    onload: function(frm) {
        frm.set_df_property('custom_age', 'read_only', 1); // 👈 makes field read only
    },
    date_of_birth: function(frm) {
        if (frm.doc.date_of_birth) {
            let age = moment().diff(frm.doc.date_of_birth, 'years');
            frm.set_value('custom_age', age);
        }
    }
});

if (!Number.isInteger(frm.doc.custom_ot_hrs)) {
    frappe.throw("OT Hours must be a whole number");
}
